-- STEP Configuration and synthetic identities
CREATE OR REPLACE FUNCTION pg_temp.demo_uuid(kind text,n integer) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$ SELECT md5('yember-rich-demo-v1:'||kind||':'||n::text)::uuid $$;
CREATE TEMP TABLE demo_config ON COMMIT DROP AS SELECT current_setting('yember.demo_customers')::int customers,current_setting('yember.demo_restaurants')::int restaurants,current_setting('yember.demo_riders')::int riders,current_setting('yember.demo_orders')::int orders;
CREATE TEMP TABLE demo_user_plan ON COMMIT DROP AS SELECT n,'customer'::text kind,'CUSTOMER'::text role FROM demo_config,generate_series(1,customers)n UNION ALL SELECT n,'owner','RESTAURANT_OWNER' FROM demo_config,generate_series(1,restaurants)n UNION ALL SELECT n,'rider','DELIVERY_PARTNER' FROM demo_config,generate_series(1,riders)n;
INSERT INTO users(uuid,full_name,email,phone,password_hash,role,status,phone_verified_at,created_at,updated_at)
SELECT pg_temp.demo_uuid(kind,n),'Demo '||(ARRAY['Ayaan','Zoya','Kabir','Sana','Arjun','Meera','Ishaan','Sara','Rehan','Anaya'])[1+n%10]||' '||(ARRAY['Mir','Sharma','Khan','Bhat','Dar','Shah','Raina','Malik'])[1+n%8]||' '||lpad(n::text,4,'0'),'demo.'||kind||'.'||lpad(n::text,4,'0')||'@yember.invalid','+910000'||CASE kind WHEN 'customer' THEN '1' WHEN 'owner' THEN '2' ELSE '3' END||lpad(n::text,5,'0'),current_setting('yember.demo_password_hash'),role,CASE WHEN kind='customer' AND n%31=0 THEN 'SUSPENDED' WHEN kind='customer' AND n%29=0 THEN 'INACTIVE' ELSE 'ACTIVE' END,now()-interval '120 days'+n*interval '1 hour',now()-interval '150 days'+n*interval '1 hour',now()-interval '120 days'+n*interval '1 hour' FROM demo_user_plan ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_users ON COMMIT DROP AS SELECT p.*,u.id,u.full_name FROM demo_user_plan p JOIN users u ON u.uuid=pg_temp.demo_uuid(p.kind,p.n);
-- STEP Service areas and profiles
INSERT INTO stations(uuid,name,description,latitude,longitude,radius_km,status,created_by,created_at,updated_at)
SELECT pg_temp.demo_uuid('station',n),'Demo '||(ARRAY['Lal Chowk','Rajbagh','Jawahar Nagar','Bemina','Hazratbal','Nigeen','Dalgate','Nishat','Shalimar','Hyderpora','Rawalpora','Sanat Nagar','Nowgam','Soura','Rainawari','Chanapora','Baghat','Zakura','Pantha Chowk','Batamaloo'])[n],'Synthetic development service area in Srinagar',34.04+(n%5)*0.004,74.78+(n/5)*0.005,5+n%4,CASE WHEN n=20 THEN 'INACTIVE' ELSE 'ACTIVE' END,current_setting('yember.actor_id')::bigint,now()-interval '120 days',now()-interval '90 days' FROM generate_series(1,20)n ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_stations ON COMMIT DROP AS SELECT n,s.* FROM generate_series(1,20)n JOIN stations s ON s.uuid=pg_temp.demo_uuid('station',n);
INSERT INTO user_addresses(uuid,user_id,label,contact_name,contact_phone,address_line1,address_line2,city,latitude,longitude,is_default,created_at,updated_at)
SELECT pg_temp.demo_uuid('address',(u.n-1)*2+j),u.id,CASE j WHEN 1 THEN 'Home' ELSE 'Work' END,u.full_name,'+9100001'||lpad(u.n::text,5,'0'),(10+u.n%90)::text||' Demo Lane',s.name,'Srinagar',s.latitude+0.001*j,s.longitude+0.001*j,j=1,now()-interval '100 days',now()-interval '80 days' FROM demo_users u JOIN demo_stations s ON s.n=1+(u.n-1)%20 CROSS JOIN generate_series(1,2)j WHERE u.kind='customer' ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_addresses ON COMMIT DROP AS SELECT u.n,a.id FROM demo_users u JOIN user_addresses a ON a.uuid=pg_temp.demo_uuid('address',(u.n-1)*2+1) WHERE u.kind='customer';
INSERT INTO restaurants(uuid,owner_user_id,station_id,name,description,phone,address,latitude,longitude,image_url,fssai_number,status,is_open,approved_by,approved_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('restaurant',u.n),u.id,s.id,'Demo '||(ARRAY['Kashmir Kitchen','Saffron Table','Dal Lake Cafe','Valley Bites','Chinar Bistro','Spice Route','Garden Bowl','Pizza Atelier','Kahwa House','Urban Tandoor'])[1+(u.n-1)%10]||' '||lpad(u.n::text,2,'0'),'Synthetic local restaurant. Fresh meals, family favourites and seasonal specials.','+9100002'||lpad(u.n::text,5,'0'),(10+u.n)::text||' Demo Market, '||s.name||', Srinagar',s.latitude,s.longitude,(SELECT url FROM demo_images WHERE name=CASE WHEN u.n%2=0 THEN 'restaurant' ELSE 'bistro' END),'DEMO-NOT-A-LICENSE-'||u.n,CASE WHEN u.n<=greatest(1,c.restaurants*8/10) THEN 'APPROVED' WHEN u.n<=c.restaurants*9/10 THEN 'PENDING' WHEN u.n%2=0 THEN 'REJECTED' ELSE 'SUSPENDED' END,u.n<=greatest(1,c.restaurants*8/10) AND u.n%7<>0,CASE WHEN u.n<=greatest(1,c.restaurants*8/10) THEN current_setting('yember.actor_id')::bigint END,CASE WHEN u.n<=greatest(1,c.restaurants*8/10) THEN now()-interval '85 days' END,now()-interval '100 days'+u.n*interval '1 hour',now()-interval '80 days' FROM demo_users u JOIN demo_stations s ON s.n=1+(u.n-1)%19 CROSS JOIN demo_config c WHERE u.kind='owner' ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_restaurants ON COMMIT DROP AS SELECT u.n,r.* FROM demo_users u JOIN restaurants r ON r.uuid=pg_temp.demo_uuid('restaurant',u.n) WHERE u.kind='owner';
INSERT INTO riders(uuid,user_id,station_id,vehicle_type,verification_status,availability_status,approved_by,created_at,updated_at)
SELECT pg_temp.demo_uuid('rider-profile',u.n),u.id,s.id,(ARRAY['MOTORCYCLE','SCOOTER','BICYCLE'])[1+u.n%3],CASE WHEN u.n<=greatest(1,c.riders*8/10) THEN 'APPROVED' WHEN u.n%2=0 THEN 'PENDING' ELSE 'REJECTED' END,CASE WHEN u.n<=greatest(1,c.riders*8/10) AND u.n%3<>0 THEN 'ONLINE' ELSE 'OFFLINE' END,CASE WHEN u.n<=greatest(1,c.riders*8/10) THEN current_setting('yember.actor_id')::bigint END,now()-interval '95 days'+u.n*interval '1 hour',now()-interval '70 days' FROM demo_users u JOIN demo_stations s ON s.n=1+(u.n-1)%19 CROSS JOIN demo_config c WHERE u.kind='rider' ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_riders ON COMMIT DROP AS SELECT u.n,r.* FROM demo_users u JOIN riders r ON r.uuid=pg_temp.demo_uuid('rider-profile',u.n) WHERE u.kind='rider';
-- STEP Onboarding documents and non-operational demo banks
INSERT INTO restaurant_documents(uuid,restaurant_id,document_type,file_url,verification_status,verified_by,verified_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('restaurant-doc',(r.n-1)*2+j),r.id,CASE j WHEN 1 THEN 'DEMO_BUSINESS_PROOF' ELSE 'DEMO_FOOD_SAFETY_PROOF' END,'/api/v1/onboarding/documents/'||pg_temp.demo_uuid('restaurant-doc',(r.n-1)*2+j),CASE WHEN r.status='APPROVED' THEN 'APPROVED' ELSE 'PENDING' END,CASE WHEN r.status='APPROVED' THEN current_setting('yember.actor_id')::bigint END,CASE WHEN r.status='APPROVED' THEN r.approved_at END,r.created_at+interval '1 hour',r.created_at+interval '2 hours' FROM demo_restaurants r CROSS JOIN generate_series(1,2)j ON CONFLICT DO NOTHING;
INSERT INTO rider_documents(uuid,rider_id,document_type,file_url,verification_status,verified_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('rider-doc',(r.n-1)*2+j),r.id,CASE j WHEN 1 THEN 'DEMO_VEHICLE_PROOF' ELSE 'DEMO_DELIVERY_PROOF' END,'/api/v1/onboarding/documents/'||pg_temp.demo_uuid('rider-doc',(r.n-1)*2+j),CASE WHEN r.verification_status='APPROVED' THEN 'APPROVED' ELSE 'PENDING' END,CASE WHEN r.verification_status='APPROVED' THEN r.created_at+interval '1 day' END,r.created_at+interval '1 hour',r.created_at+interval '2 hours' FROM demo_riders r CROSS JOIN generate_series(1,2)j ON CONFLICT DO NOTHING;
INSERT INTO restaurant_bank_accounts(uuid,restaurant_id,account_holder,account_number_encrypted,bank_name,ifsc,verification_status,created_at,updated_at)
SELECT pg_temp.demo_uuid('restaurant-bank',r.n),r.id,'DEMO ONLY - '||r.name,jsonb_build_object('format','demo-only','last_four',lpad(r.n::text,4,'0'),'fixture',true)::text,'Demo Bank - no real account','DEMO0000000',CASE WHEN r.status='APPROVED' THEN 'VERIFIED' ELSE 'PENDING' END,r.created_at+interval '1 day',r.created_at+interval '2 days' FROM demo_restaurants r ON CONFLICT DO NOTHING;
INSERT INTO delivery_agent_bank_details(uuid,rider_id,account_holder,account_number_encrypted,bank_name,ifsc,verification_status,created_at,updated_at)
SELECT pg_temp.demo_uuid('rider-bank',r.n),r.id,'DEMO ONLY - Agent '||r.n,jsonb_build_object('format','demo-only','last_four',lpad(r.n::text,4,'0'),'fixture',true)::text,'Demo Bank - no real account','DEMO0000000',CASE WHEN r.verification_status='APPROVED' THEN 'VERIFIED' ELSE 'PENDING' END,r.created_at+interval '1 day',r.created_at+interval '2 days' FROM demo_riders r ON CONFLICT DO NOTHING;
-- STEP Catalog with verified public images
CREATE TEMP TABLE demo_dishes(n int,name text,description text,price numeric,photo text,category int) ON COMMIT DROP;
INSERT INTO demo_dishes VALUES
(1,'Creamy herb pasta','Creamy pasta with garden herbs and vegetables.',229,'pasta',1),(2,'Garden margherita pizza','Stone-baked pizza with mozzarella, basil and tomato.',299,'pizza',2),(3,'Roasted vegetable pizza','Seasonal vegetables and cheese on a crisp base.',329,'vegetable-pizza',2),(4,'Classic cheese pizza','Rich cheese and herb pizza, baked to order.',279,'cheese-pizza',2),(5,'House curry and rice','A warming curry served with basmati rice.',249,'curry',3),(6,'Kebab rice platter','Grilled kebab with fragrant rice.',349,'kebab',4),(7,'House signature burger','A burger with crisp lettuce and house sauce.',199,'burger',5),(8,'Fresh vegetable salad','Seasonal greens and vegetables.',179,'salad',6),(9,'Garden lunch bowl','Mixed greens with a light dressing.',189,'garden-salad',6),(10,'House espresso coffee','Freshly brewed espresso.',119,'coffee',7),(11,'Pesto pasta bowl','Herbed pasta with house pesto sauce.',259,'pasta',1),(12,'Family vegetable pizza','Vegetable pizza for sharing.',449,'vegetable-pizza',2),(13,'Spiced rice and curry','Fragrant rice with slow-cooked curry.',269,'curry',3),(14,'Grilled kebab special','A hearty kebab and rice platter.',379,'kebab',4),(15,'Double house burger','A larger signature house burger.',279,'burger',5),(16,'Vegan harvest salad','Seasonal ingredients with a vegan dressing.',209,'vegan-salad',6),(17,'Cappuccino','Espresso topped with steamed milk.',149,'coffee',7),(18,'Cheesy pasta bake','Oven-finished pasta with cheese sauce.',289,'pasta',1),(19,'Lunch curry combo','A complete lunch of curry and rice.',299,'curry',3),(20,'Chef garden salad','Fresh market produce of the day.',219,'garden-salad',6);
INSERT INTO menu_categories(uuid,name,description,image_url,sort_order,is_active,created_at,updated_at)
SELECT pg_temp.demo_uuid('category',n),'Demo '||(ARRAY['Pasta','Pizza','Rice and curry','Grills','Burgers','Salads','Coffee','Family meals','Lunch specials','Chef favourites','Light bites','Weekend specials','Vegetarian picks','Sharing plates','Seasonal menu'])[n],'Synthetic catalog category',(SELECT url FROM demo_images WHERE n=1+(g.n-1)%10),n,n<>15,now()-interval '110 days',now()-interval '80 days' FROM generate_series(1,15)g(n) ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_categories ON COMMIT DROP AS SELECT n,c.id FROM generate_series(1,15)n JOIN menu_categories c ON c.uuid=pg_temp.demo_uuid('category',n);
INSERT INTO menu_items(uuid,restaurant_id,category_id,name,description,base_price,image_url,preparation_minutes,is_available,created_at,updated_at)
SELECT pg_temp.demo_uuid('item',(r.n-1)*20+d.n),r.id,c.id,d.name,d.description,d.price+(r.n%3)*10,i.url,10+d.n%6*5,d.n%11<>0,r.created_at+interval '2 days',r.created_at+interval '3 days' FROM demo_restaurants r CROSS JOIN demo_dishes d JOIN demo_categories c ON c.n=d.category JOIN demo_images i ON i.name=d.photo ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_items ON COMMIT DROP AS SELECT r.n restaurant_n,d.n dish_n,m.* FROM demo_restaurants r CROSS JOIN demo_dishes d JOIN menu_items m ON m.uuid=pg_temp.demo_uuid('item',(r.n-1)*20+d.n);
INSERT INTO item_variants(uuid,menu_item_id,name,price_delta,is_available,created_at,updated_at)
SELECT pg_temp.demo_uuid('variant',(m.restaurant_n-1)*40+(m.dish_n-1)*2+j),m.id,CASE j WHEN 1 THEN 'Regular' ELSE 'Large' END,CASE j WHEN 1 THEN 0 ELSE 60 END,true,m.created_at,m.updated_at FROM demo_items m CROSS JOIN generate_series(1,2)j ON CONFLICT DO NOTHING;
-- STEP Promotions and carts
INSERT INTO coupons(uuid,code,description,discount_type,discount_value,min_order_amount_paise,max_discount_amount_paise,valid_from,valid_until,usage_limit,is_active,created_at,updated_at)
SELECT pg_temp.demo_uuid('coupon',n),'DEMO'||lpad(n::text,3,'0'),'Synthetic promotion '||n,CASE WHEN n%2=0 THEN 'FLAT' ELSE 'PERCENTAGE' END,CASE WHEN n%2=0 THEN 5000 ELSE 10 END,10000,10000,now()-interval '90 days',CASE WHEN n%5=0 THEN now()-interval '1 day' ELSE now()+interval '90 days' END,10000,n%7<>0,now()-interval '90 days',now()-interval '80 days' FROM generate_series(1,40)n ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_coupons ON COMMIT DROP AS SELECT n,c.* FROM generate_series(1,40)n JOIN coupons c ON c.uuid=pg_temp.demo_uuid('coupon',n);
INSERT INTO carts(uuid,user_id,restaurant_id,status,expires_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('cart',u.n),u.id,r.id,CASE WHEN u.n%5=0 THEN 'ABANDONED' ELSE 'ACTIVE' END,CASE WHEN u.n%5=0 THEN now()-interval '1 day' ELSE now()+interval '2 hours' END,now()-interval '2 hours',now()-interval '1 hour' FROM demo_users u CROSS JOIN demo_config cfg JOIN demo_restaurants r ON r.n=1+(u.n-1)%greatest(1,cfg.restaurants*8/10) WHERE u.kind='customer' ON CONFLICT DO NOTHING;
INSERT INTO cart_items(uuid,cart_id,menu_item_id,variant_id,quantity,special_instructions,created_at,updated_at)
SELECT pg_temp.demo_uuid('cart-item',(u.n-1)*3+j),cart.id,m.id,v.id,1+u.n%2,CASE WHEN j=1 THEN 'Demo: mild spice please' ELSE 'Demo fixture' END,cart.created_at,cart.updated_at FROM demo_users u JOIN carts cart ON cart.uuid=pg_temp.demo_uuid('cart',u.n) CROSS JOIN generate_series(1,3)j JOIN demo_items m ON m.restaurant_id=cart.restaurant_id AND m.dish_n=j JOIN item_variants v ON v.menu_item_id=m.id AND v.name='Regular' WHERE u.kind='customer' ON CONFLICT DO NOTHING;
-- STEP Orders and delivery assignments
CREATE TEMP TABLE demo_order_plan ON COMMIT DROP AS
SELECT g.n,r.id restaurant_id,u.id user_id,a.id address_id,rider.id rider_id,CASE WHEN g.n%20<13 THEN 'DELIVERED' WHEN g.n%20=13 THEN 'CANCELLED' WHEN g.n%20=14 THEN 'REJECTED' WHEN g.n%20=15 THEN 'CONFIRMED' WHEN g.n%20=16 THEN 'ACCEPTED' WHEN g.n%20=17 THEN 'PREPARING' WHEN g.n%20=18 THEN 'READY_FOR_PICKUP' ELSE 'OUT_FOR_DELIVERY' END status,now()-make_interval(days=>g.n%60,hours=>g.n%20,mins=>g.n%53)-interval '2 hours' placed_at,CASE WHEN g.n%5=0 THEN 50::numeric ELSE 0::numeric END discount,(SELECT sum(m.base_price) FROM demo_items m WHERE m.restaurant_id=r.id AND m.dish_n BETWEEN 1+((g.n*3)%18) AND 3+((g.n*3)%18)) subtotal
FROM demo_config cfg CROSS JOIN generate_series(1,cfg.orders)g(n) JOIN demo_restaurants r ON r.n=1+(g.n-1)%greatest(1,cfg.restaurants*8/10) JOIN demo_users u ON u.kind='customer' AND u.n=1+(g.n-1)%cfg.customers JOIN demo_addresses a ON a.n=u.n JOIN demo_riders rider ON rider.n=1+(g.n-1)%greatest(1,cfg.riders*8/10);
INSERT INTO orders(uuid,order_number,user_id,restaurant_id,address_id,status,subtotal,delivery_fee,tax_amount,discount_amount,total_amount,currency,placed_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('order',n),'DEMO-V1-'||lpad(n::text,7,'0'),user_id,restaurant_id,address_id,status,subtotal,40,round(subtotal*0.05,2),discount,subtotal+40+round(subtotal*0.05,2)-discount,'INR',placed_at,placed_at,placed_at+interval '45 minutes' FROM demo_order_plan ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_orders ON COMMIT DROP AS SELECT p.n,p.rider_id,o.* FROM demo_order_plan p JOIN orders o ON o.uuid=pg_temp.demo_uuid('order',p.n);
INSERT INTO order_items(uuid,order_id,menu_item_id,variant_id,quantity,unit_price,special_instructions,created_at,updated_at)
SELECT pg_temp.demo_uuid('order-line',(o.n-1)*3+j),o.id,m.id,v.id,1,m.base_price,CASE WHEN j=1 AND o.n%3=0 THEN 'Demo: mild spice please' ELSE 'Synthetic development order' END,o.created_at,o.updated_at FROM demo_orders o CROSS JOIN generate_series(1,3)j JOIN demo_items m ON m.restaurant_id=o.restaurant_id AND m.dish_n=((o.n*3)%18)+j JOIN item_variants v ON v.menu_item_id=m.id AND v.name='Regular' ON CONFLICT DO NOTHING;
INSERT INTO delivery_assignments(uuid,order_id,rider_id,status,assigned_at,accepted_at,picked_up_at,delivered_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('assignment',n),id,rider_id,CASE WHEN status='DELIVERED' THEN 'DELIVERED' WHEN status='OUT_FOR_DELIVERY' THEN 'OUT_FOR_DELIVERY' ELSE 'ASSIGNED' END,placed_at+interval '20 minutes',CASE WHEN status IN ('DELIVERED','OUT_FOR_DELIVERY') THEN placed_at+interval '22 minutes' END,CASE WHEN status IN ('DELIVERED','OUT_FOR_DELIVERY') THEN placed_at+interval '30 minutes' END,CASE WHEN status='DELIVERED' THEN placed_at+interval '45 minutes' END,created_at+interval '20 minutes',updated_at FROM demo_orders WHERE status IN ('DELIVERED','READY_FOR_PICKUP','OUT_FOR_DELIVERY') ON CONFLICT DO NOTHING;
INSERT INTO coupon_usages(uuid,coupon_id,user_id,order_id,discount_amount_paise,redeemed_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('coupon-usage',o.n),c.id,o.user_id,o.id,round(o.discount_amount*100)::bigint,o.placed_at,o.created_at,o.created_at FROM demo_orders o JOIN demo_coupons c ON c.n=2*((o.n/5)%20)+2 WHERE o.discount_amount>0 AND o.status NOT IN ('CANCELLED','REJECTED') ON CONFLICT DO NOTHING;
-- STEP Demo payments and registration fees
INSERT INTO payment_intents(uuid,order_id,purpose,method,stage,amount_paise,currency,status,provider_order_id,idempotency_key,expires_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('order-intent',n),id,'ORDER',CASE WHEN n%3=0 THEN 'PAY_ON_DELIVERY' ELSE 'RAZORPAY' END,'ORDER',round(total_amount*100)::bigint,'INR',CASE WHEN status IN ('CANCELLED','REJECTED') THEN 'CANCELLED' WHEN status='DELIVERED' OR n%3<>0 THEN 'SUCCEEDED' ELSE 'CREATED' END,'DEMO_ORDER_'||n,'demo-v1/order/'||n,placed_at+interval '2 hours',created_at,updated_at FROM demo_orders ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_payments_plan ON COMMIT DROP AS SELECT o.n,o.id order_id,pi.id intent_id,round(o.total_amount*100)::bigint amount,CASE WHEN o.n%3=0 THEN 'CASH' WHEN o.n%2=0 THEN 'CARD' ELSE 'UPI' END method,o.created_at,o.updated_at,o.status FROM demo_orders o JOIN payment_intents pi ON pi.uuid=pg_temp.demo_uuid('order-intent',o.n) WHERE o.status NOT IN ('CANCELLED','REJECTED') AND (o.status='DELIVERED' OR o.n%3<>0);
INSERT INTO payments(uuid,payment_intent_id,order_id,provider,provider_payment_id,method,amount_paise,currency,status,received_by,captured_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('order-payment',n),intent_id,order_id,'DEMO','DEMO_PAYMENT_'||n,method,amount,'INR','CAPTURED',CASE WHEN method='CASH' THEN 'AGENT' ELSE 'YEMBER' END,CASE WHEN method='CASH' THEN updated_at ELSE created_at+interval '1 minute' END,created_at,updated_at FROM demo_payments_plan ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_payments ON COMMIT DROP AS SELECT p.n,p.method demo_method,p.amount,pay.* FROM demo_payments_plan p JOIN payments pay ON pay.uuid=pg_temp.demo_uuid('order-payment',p.n);
CREATE TEMP TABLE demo_registration_plan ON COMMIT DROP AS SELECT 'restaurant'::text kind,n,id owner_id,status='APPROVED' paid,20000::bigint amount,created_at FROM demo_restaurants UNION ALL SELECT 'agent',n,id,verification_status='APPROVED',15000::bigint,created_at FROM demo_riders;
INSERT INTO payment_intents(uuid,restaurant_id,delivery_agent_id,purpose,method,stage,amount_paise,currency,status,provider_order_id,idempotency_key,created_at,updated_at)
SELECT pg_temp.demo_uuid(kind||'-registration-intent',n),CASE WHEN kind='restaurant' THEN owner_id END,CASE WHEN kind='agent' THEN owner_id END,CASE WHEN kind='restaurant' THEN 'RESTAURANT_REGISTRATION' ELSE 'AGENT_REGISTRATION' END,'RAZORPAY','REGISTRATION',amount,'INR',CASE WHEN paid THEN 'SUCCEEDED' ELSE 'CREATED' END,'DEMO_REG_'||kind||'_'||n,'demo-v1/registration/'||kind||'/'||n,created_at,created_at+interval '1 day' FROM demo_registration_plan ON CONFLICT DO NOTHING;
INSERT INTO registration_fees(uuid,restaurant_id,delivery_agent_id,amount_paise,currency,payment_intent_id,status,paid_at,created_at,updated_at)
SELECT pg_temp.demo_uuid(p.kind||'-registration-fee',p.n),CASE WHEN p.kind='restaurant' THEN p.owner_id END,CASE WHEN p.kind='agent' THEN p.owner_id END,p.amount,'INR',i.id,CASE WHEN p.paid THEN 'PAID' ELSE 'DUE' END,CASE WHEN p.paid THEN p.created_at+interval '1 day' END,p.created_at,p.created_at+interval '1 day' FROM demo_registration_plan p JOIN payment_intents i ON i.uuid=pg_temp.demo_uuid(p.kind||'-registration-intent',p.n) ON CONFLICT DO NOTHING;
INSERT INTO payments(uuid,payment_intent_id,provider,provider_payment_id,method,amount_paise,currency,status,received_by,captured_at,created_at,updated_at)
SELECT pg_temp.demo_uuid(p.kind||'-registration-payment',p.n),i.id,'DEMO','DEMO_REG_PAYMENT_'||p.kind||'_'||p.n,'UPI',p.amount,'INR','CAPTURED','YEMBER',p.created_at+interval '1 day',p.created_at,p.created_at+interval '1 day' FROM demo_registration_plan p JOIN payment_intents i ON i.uuid=pg_temp.demo_uuid(p.kind||'-registration-intent',p.n) WHERE p.paid ON CONFLICT DO NOTHING;
-- STEP Earnings and payouts
INSERT INTO restaurant_earnings(uuid,restaurant_id,order_id,gross_amount_paise,fee_amount_paise,adjustment_amount_paise,net_amount_paise,status,eligible_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('restaurant-earning',o.n),o.restaurant_id,o.id,round(o.subtotal*100)::bigint,round(o.subtotal*10)::bigint,0,round(o.subtotal*100)::bigint-round(o.subtotal*10)::bigint,CASE WHEN o.n%4=0 THEN 'SETTLED' ELSE 'AVAILABLE' END,o.updated_at,o.created_at,o.updated_at FROM demo_orders o WHERE o.status='DELIVERED' ON CONFLICT DO NOTHING;
INSERT INTO delivery_agent_earnings(uuid,delivery_agent_id,order_id,base_amount_paise,incentive_amount_paise,adjustment_amount_paise,net_amount_paise,status,eligible_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('agent-earning',o.n),o.rider_id,o.id,4000,0,0,4000,CASE WHEN o.n%4=0 THEN 'SETTLED' ELSE 'AVAILABLE' END,o.updated_at,o.created_at,o.updated_at FROM demo_orders o WHERE o.status='DELIVERED' ON CONFLICT DO NOTHING;
CREATE TEMP TABLE demo_re ON COMMIT DROP AS SELECT o.n,e.* FROM demo_orders o JOIN restaurant_earnings e ON e.uuid=pg_temp.demo_uuid('restaurant-earning',o.n);
CREATE TEMP TABLE demo_ae ON COMMIT DROP AS SELECT o.n,e.* FROM demo_orders o JOIN delivery_agent_earnings e ON e.uuid=pg_temp.demo_uuid('agent-earning',o.n);
INSERT INTO restaurant_payouts(uuid,restaurant_id,order_id,method,amount_paise,status,provider_transfer_id,confirmed_by_restaurant_at,paid_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('restaurant-payout',n),restaurant_id,order_id,'BANK_TRANSFER',net_amount_paise,CASE WHEN n%4=0 THEN 'PAID' ELSE 'PENDING' END,'DEMO_TRANSFER_REST_'||n,CASE WHEN n%4=0 THEN updated_at+interval '1 hour' END,CASE WHEN n%4=0 THEN updated_at+interval '1 hour' END,created_at,updated_at FROM demo_re WHERE n%4 IN (0,1) ON CONFLICT DO NOTHING;
INSERT INTO delivery_agent_payouts(uuid,delivery_agent_id,bank_details_id,method,amount_paise,status,provider_transfer_id,paid_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('agent-payout',e.n),e.delivery_agent_id,b.id,'BANK_TRANSFER',e.net_amount_paise,CASE WHEN e.n%4=0 THEN 'PAID' ELSE 'PENDING' END,'DEMO_TRANSFER_AGENT_'||e.n,CASE WHEN e.n%4=0 THEN e.updated_at+interval '1 hour' END,e.created_at,e.updated_at FROM demo_ae e JOIN delivery_agent_bank_details b ON b.rider_id=e.delivery_agent_id AND b.uuid=pg_temp.demo_uuid('rider-bank',(SELECT n FROM demo_riders WHERE id=e.delivery_agent_id)) WHERE e.n%4 IN (0,1) ON CONFLICT DO NOTHING;
INSERT INTO restaurant_payout_allocations(uuid,restaurant_payout_id,restaurant_earning_id,amount_paise,created_at,updated_at)
SELECT pg_temp.demo_uuid('restaurant-allocation',e.n),p.id,e.id,e.net_amount_paise,e.created_at,e.updated_at FROM demo_re e JOIN restaurant_payouts p ON p.uuid=pg_temp.demo_uuid('restaurant-payout',e.n) ON CONFLICT DO NOTHING;
INSERT INTO delivery_agent_payout_allocations(uuid,delivery_agent_payout_id,delivery_agent_earning_id,amount_paise,created_at,updated_at)
SELECT pg_temp.demo_uuid('agent-allocation',e.n),p.id,e.id,e.net_amount_paise,e.created_at,e.updated_at FROM demo_ae e JOIN delivery_agent_payouts p ON p.uuid=pg_temp.demo_uuid('agent-payout',e.n) ON CONFLICT DO NOTHING;
INSERT INTO cash_collections(uuid,order_id,delivery_agent_id,restaurant_id,amount_due_paise,amount_collected_paise,collected_at,status,created_at,updated_at)
SELECT pg_temp.demo_uuid('cash',n),id,rider_id,restaurant_id,round(total_amount*100)::bigint,round(total_amount*100)::bigint,updated_at,'COLLECTED',created_at,updated_at FROM demo_orders WHERE status='DELIVERED' AND n%3=0 ON CONFLICT DO NOTHING;
-- STEP Balanced append-only financial events
CREATE TEMP TABLE demo_postings(event text,kind text,account text,direction text,amount bigint,order_id bigint,payment_id bigint,restaurant_earning_id bigint,agent_earning_id bigint,restaurant_payout_id bigint,agent_payout_id bigint,registration_fee_id bigint,occurred_at timestamptz) ON COMMIT DROP;
INSERT INTO demo_postings SELECT 'demo-v1/collection/'||p.n,'COLLECTION',CASE WHEN p.demo_method='CASH' THEN 'CASH_IN_CUSTODY' ELSE 'YEMBER_BANK' END,'DEBIT',p.amount,p.order_id,p.id,NULL::bigint,NULL::bigint,NULL::bigint,NULL::bigint,NULL::bigint,p.captured_at FROM demo_payments p UNION ALL SELECT 'demo-v1/collection/'||p.n,'COLLECTION','ORDER_RECEIPTS','CREDIT',p.amount,p.order_id,p.id,NULL::bigint,NULL::bigint,NULL::bigint,NULL::bigint,NULL::bigint,p.captured_at FROM demo_payments p;
INSERT INTO demo_postings SELECT 'demo-v1/earning/'||o.n,'EARNING',line.account,line.direction,line.amount,o.id,p.id,re.id,ae.id,NULL::bigint,NULL::bigint,NULL::bigint,o.updated_at FROM demo_orders o JOIN demo_payments p ON p.order_id=o.id JOIN demo_re re ON re.order_id=o.id JOIN demo_ae ae ON ae.order_id=o.id CROSS JOIN LATERAL (VALUES ('ORDER_RECEIPTS','DEBIT',round(o.total_amount*100)::bigint),('PROMOTION_EXPENSE','DEBIT',round(o.discount_amount*100)::bigint),('RESTAURANT_PAYABLE','CREDIT',re.net_amount_paise),('PLATFORM_FEE_REVENUE','CREDIT',re.fee_amount_paise),('TAX_PAYABLE','CREDIT',round(o.tax_amount*100)::bigint),('AGENT_PAYABLE','CREDIT',ae.net_amount_paise)) AS line(account,direction,amount) WHERE line.amount>0;
INSERT INTO demo_postings SELECT 'demo-v1/payout/rest/'||e.n,'PAYOUT',line.account,line.direction,e.net_amount_paise,e.order_id,NULL::bigint,e.id,NULL::bigint,p.id,NULL::bigint,NULL::bigint,p.paid_at FROM demo_re e JOIN restaurant_payouts p ON p.uuid=pg_temp.demo_uuid('restaurant-payout',e.n) CROSS JOIN (VALUES ('RESTAURANT_PAYABLE','DEBIT'),('YEMBER_BANK','CREDIT'))line(account,direction) WHERE p.status='PAID';
INSERT INTO demo_postings SELECT 'demo-v1/payout/agent/'||e.n,'PAYOUT',line.account,line.direction,e.net_amount_paise,e.order_id,NULL::bigint,NULL::bigint,e.id,NULL::bigint,p.id,NULL::bigint,p.paid_at FROM demo_ae e JOIN delivery_agent_payouts p ON p.uuid=pg_temp.demo_uuid('agent-payout',e.n) CROSS JOIN (VALUES ('AGENT_PAYABLE','DEBIT'),('YEMBER_BANK','CREDIT'))line(account,direction) WHERE p.status='PAID';
INSERT INTO demo_postings SELECT 'demo-v1/registration/'||p.kind||'/'||p.n,'REGISTRATION',line.account,line.direction,p.amount,NULL::bigint,pay.id,NULL::bigint,NULL::bigint,NULL::bigint,NULL::bigint,f.id,p.created_at+interval '1 day' FROM demo_registration_plan p JOIN payments pay ON pay.uuid=pg_temp.demo_uuid(p.kind||'-registration-payment',p.n) JOIN registration_fees f ON f.uuid=pg_temp.demo_uuid(p.kind||'-registration-fee',p.n) CROSS JOIN (VALUES ('YEMBER_BANK','DEBIT'),('REGISTRATION_FEE_REVENUE','CREDIT'))line(account,direction) WHERE p.paid;
INSERT INTO financial_transactions(uuid,order_id,payment_id,restaurant_earning_id,agent_earning_id,restaurant_payout_id,agent_payout_id,registration_fee_id,transaction_type,account_code,direction,amount_paise,currency,event_key,occurred_at,created_at,updated_at)
SELECT md5(event||'/'||account||'/'||direction)::uuid,order_id,payment_id,restaurant_earning_id,agent_earning_id,restaurant_payout_id,agent_payout_id,registration_fee_id,kind,account,direction,amount,'INR',event||':'||account,occurred_at,occurred_at,occurred_at FROM demo_postings ON CONFLICT DO NOTHING;
-- STEP Refunds, provider event fixtures and reconciliation
INSERT INTO refunds(uuid,payment_id,order_id,amount_paise,reason,provider_refund_id,status,completed_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('refund',o.n),p.id,o.id,2500,'DEMO ONLY: synthetic partial refund fixture','DEMO_REFUND_'||o.n,CASE WHEN o.n%3=0 THEN 'PENDING' ELSE 'COMPLETED' END,CASE WHEN o.n%3<>0 THEN o.updated_at+interval '2 hours' END,o.updated_at+interval '1 hour',o.updated_at+interval '2 hours' FROM demo_orders o JOIN demo_payments p ON p.order_id=o.id WHERE o.n%11=0 AND o.status='DELIVERED' ON CONFLICT DO NOTHING;
INSERT INTO financial_transactions(uuid,order_id,payment_id,transaction_type,account_code,direction,amount_paise,currency,event_key,occurred_at,created_at,updated_at)
SELECT md5('demo-v1/refund/'||o.n||':'||line.account)::uuid,o.id,p.id,'REFUND',line.account,line.direction,2500,'INR','demo-v1/refund/'||o.n||':'||line.account,r.completed_at,r.created_at,r.updated_at FROM demo_orders o JOIN demo_payments p ON p.order_id=o.id JOIN refunds r ON r.uuid=pg_temp.demo_uuid('refund',o.n) CROSS JOIN (VALUES ('REFUND_EXPENSE','DEBIT'),('YEMBER_BANK','CREDIT'))line(account,direction) WHERE r.status='COMPLETED' ON CONFLICT DO NOTHING;
INSERT INTO payment_webhook_events(uuid,provider,provider_event_id,event_type,payload_json,signature_valid,processing_status,processed_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('webhook',p.n),'DEMO','DEMO_EVENT_'||p.n,'payment.captured',jsonb_build_object('demo',true,'synthetic',true,'payment_reference',p.provider_payment_id),true,CASE WHEN p.n%17=0 THEN 'IGNORED' ELSE 'PROCESSED' END,p.updated_at,p.created_at,p.updated_at FROM demo_payments p ON CONFLICT DO NOTHING;
INSERT INTO reconciliation_runs(uuid,source,period_start,period_end,status,difference_paise,summary_json,created_at,updated_at)
SELECT pg_temp.demo_uuid('reconciliation',n),'DEMO',date_trunc('day',now())-n*interval '1 day',date_trunc('day',now())-(n-1)*interval '1 day',CASE WHEN n%9=0 THEN 'EXCEPTIONS' ELSE 'COMPLETED' END,CASE WHEN n%9=0 THEN 2500 ELSE 0 END,jsonb_build_object('demo',true,'transactions_checked',50+n,'note','Synthetic reconciliation; no external provider contacted'),now()-n*interval '1 day',now()-n*interval '1 day' FROM generate_series(1,120)n ON CONFLICT DO NOTHING;
-- STEP Expired security fixtures and location history
INSERT INTO otp_challenges(uuid,user_id,phone,purpose,otp_hash,expires_at,attempts,consumed_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('otp',u.n),u.id,'+9100001'||lpad(u.n::text,5,'0'),'LOGIN',encode(sha256(convert_to('demo-only-expired-'||u.n,'UTF8')),'hex'),now()-interval '1 day',1,now()-interval '1 day 1 minute',now()-interval '2 days',now()-interval '1 day' FROM demo_users u WHERE u.kind='customer' ON CONFLICT DO NOTHING;
INSERT INTO refresh_tokens(uuid,user_id,token_hash,expires_at,revoked_at,last_used_at,device_label,user_agent,created_at,updated_at)
SELECT pg_temp.demo_uuid('session',u.n),u.id,encode(sha256(convert_to('demo-only-revoked-'||u.n,'UTF8')),'hex'),now()-interval '1 day',now()-interval '1 day',now()-interval '2 days','Demo device '||u.n,'Synthetic fixture - not a usable session',now()-interval '7 days',now()-interval '1 day' FROM demo_users u WHERE u.kind='customer' ON CONFLICT DO NOTHING;
INSERT INTO rider_locations(uuid,rider_id,latitude,longitude,recorded_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('location',(r.n-1)*10+j),r.id,s.latitude+0.0002*j,s.longitude+0.0001*j,now()-j*interval '30 seconds',now()-j*interval '30 seconds',now()-j*interval '30 seconds' FROM demo_riders r JOIN demo_stations s ON s.id=r.station_id CROSS JOIN generate_series(1,10)j ON CONFLICT DO NOTHING;
-- STEP Historical synthetic activity and existing local image gaps
INSERT INTO system_activity_logs(uuid,actor_type,actor_id,action,entity_type,entity_id,entity_uuid,before_json,after_json,request_id,ip_address,user_agent,occurred_at,created_at,updated_at)
SELECT pg_temp.demo_uuid('audit',g.n),CASE WHEN g.n%3=0 THEN 'RESTAURANT' WHEN g.n%3=1 THEN 'USER' ELSE 'AGENT' END,u.id,(ARRAY['CREATE','UPDATE','APPROVE','VERIFY','DEMO_REVIEW'])[1+g.n%5],'RESTAURANTS',r.id,r.uuid,jsonb_build_object('status','PENDING'),jsonb_build_object('status',r.status,'change_reason','Synthetic development activity example'),'demo-history-'||g.n,('192.0.2.'||(1+g.n%250))::inet,'Yember demo fixture',now()-make_interval(days=>g.n%60,mins=>g.n%1439),now()-make_interval(days=>g.n%60,mins=>g.n%1439),now()-make_interval(days=>g.n%60,mins=>g.n%1439)
FROM demo_config cfg CROSS JOIN generate_series(1,cfg.orders)g(n) JOIN demo_restaurants r ON r.n=1+(g.n-1)%cfg.restaurants JOIN demo_users u ON u.n=1 AND u.kind=CASE WHEN g.n%3=0 THEN 'owner' WHEN g.n%3=1 THEN 'customer' ELSE 'rider' END ON CONFLICT DO NOTHING;
UPDATE restaurants SET image_url=(SELECT url FROM demo_images WHERE name='restaurant') WHERE uuid='10000000-0000-4000-a000-000000000010' AND (image_url IS NULL OR image_url='');
UPDATE menu_categories SET image_url=(SELECT url FROM demo_images WHERE name='curry') WHERE uuid='10000000-0000-4000-a000-000000000030' AND (image_url IS NULL OR image_url='');
UPDATE menu_items SET image_url=(SELECT url FROM demo_images WHERE name='curry') WHERE uuid='10000000-0000-4000-a000-000000000041' AND (image_url IS NULL OR image_url='');
